	for i := range a {
		a[i] = readInt()
	}
	slices.Sort(a)
	a = slices.Compact(a)
	gap := a[0] + total - a[len(a)-1] // the wrap-around gap
	for i := 1; i < len(a); i++ {
		gap = max(gap, a[i]-a[i-1])
	}
